// ─── AvatarWithIcon ───────────────────────────────────────────────────────────

export interface AvatarWithIconProps extends AvatarProps {
  icon: React.ReactNode;
  iconBackground?: boolean | string;
  src?: string;
  alt?: string;
  fallback?: string;
}

export function AvatarWithIcon({
  icon,
  iconBackground = true,
  src,
  alt = "Avatar",
  fallback,
  size = "md",
  className,
  ...props
}: AvatarWithIconProps) {
  const badgeSizes = {
    xs: "h-3 w-3 -bottom-[3px] -right-[2px]",
    sm: "h-3.5 w-3.5 -bottom-[4px] -right-[3px]",
    md: "h-4 w-4 -bottom-[5px] -right-[3px]",
    lg: "h-5 w-5 -bottom-[5px] -right-[3px]",
    xl: "h-6 w-6 -bottom-[6px] -right-[4px]",
  } as const satisfies Record<AvatarPresetSize, string>;
  const badgeSizeClass =
    typeof size === "number"
      ? "h-[var(--avatar-badge-size)] w-[var(--avatar-badge-size)] -bottom-[5px] -right-[3px]"
      : badgeSizes[size];
  const badgeStyle =
    typeof size === "number"
      ? ({
          "--avatar-badge-size": `${Math.max(12, Math.round(size * 0.4))}px`,
        } as React.CSSProperties)
      : undefined;

  return (
    <div className="relative inline-flex">
      <Avatar size={size} className={cn("border border-border", className)} {...props}>
        {src && <AvatarImage src={src} alt={alt} />}
        <AvatarFallback size={size}>{fallback ?? getAvatarInitials(alt)}</AvatarFallback>
      </Avatar>
      <span
        aria-hidden="true"
        className={cn(
          "absolute flex items-center justify-center overflow-hidden rounded-full border border-background",
          iconBackground === true ? "bg-background" : iconBackground || "",
          badgeSizeClass,
        )}
        style={badgeStyle}
      >
        {icon}
      </span>
    </div>
  );
}

// ─── DiceBearAvatar ───────────────────────────────────────────────────────────

export type DiceBearStyle =
  | "avataaars"
  | "avataaars-neutral"
  | "bottts"
  | "bottts-neutral"
  | "identicon"
  | "lorelei"
  | "lorelei-neutral"
  | "notionists"
  | "notionists-neutral"
  | "open-peeps"
  | "pixel-art"
  | "pixel-art-neutral"
  | "shapes"
  | "thumbs"
  | "fun-emoji"
  | "micah"
  | "miniavs"
  | "rings"
  | "croodles"
  | "croodles-neutral"
  | "dylan"
  | "glass";

export interface DiceBearAvatarProps extends Omit<AvatarProps, "style"> {
  seed: string;
  avatarStyle?: DiceBearStyle;
  options?: Record<string, string | number>;
  style?: React.CSSProperties;
}

export function DiceBearAvatar({
  seed,
  avatarStyle = "bottts-neutral",
  options = {},
  size = "md",
  className,
  ...props
}: DiceBearAvatarProps) {
  const params = new URLSearchParams({
    seed,
    ...Object.fromEntries(Object.entries(options).map(([k, v]) => [k, String(v)])),
  });
  const url = `https://api.dicebear.com/9.x/${avatarStyle}/svg?${params}`;

  return (
    <Avatar size={size} className={cn(className)} {...props}>
      <AvatarImage src={url} alt={`Avatar for ${seed}`} />
      <AvatarFallback size={size}>{getAvatarInitials(seed)}</AvatarFallback>
    </Avatar>
  );
}
