"use client";

import { Cross as XIcon } from "@nebutra/icons";
import { Command as CommandPrimitive, useCommandState } from "cmdk";
import * as React from "react";
import { type Ref, useEffect } from "react";

import { useDebouncedValue } from "../hooks/use-debounced-refresh";
import { cn } from "../utils/cn";
import { Command, CommandGroup, CommandItem, CommandList } from "./command";

export interface MultipleSelectorOption {
  value: string;
  label: string;
  disable?: boolean;
  /** Fixed option that can't be removed */
  fixed?: boolean;
  /** Group the options by providing key */
  [key: string]: string | boolean | undefined;
}

interface GroupOption {
  [key: string]: MultipleSelectorOption[];
}

type MultipleSelectorCommandFilter = NonNullable<
  React.ComponentPropsWithoutRef<typeof Command>["filter"]
>;

export interface MultipleSelectorProps {
  /** Controlled selected values */
  value?: MultipleSelectorOption[];
  /** Default options to display */
  defaultOptions?: MultipleSelectorOption[];
  /** Manually controlled options */
  options?: MultipleSelectorOption[];
  /** Placeholder text */
  placeholder?: string;
  /** Loading indicator component */
  loadingIndicator?: React.ReactNode;
  /** Empty state indicator component */
  emptyIndicator?: React.ReactNode;
  /** Debounce delay for async search (ms) */
  delay?: number;
  /** Trigger search on focus */
  triggerSearchOnFocus?: boolean;
  /** Async search function */
  onSearch?: (value: string) => Promise<MultipleSelectorOption[]>;
  /** Sync search function (no loading indicator) */
  onSearchSync?: (value: string) => MultipleSelectorOption[];
  /** Callback when selection changes */
  onChange?: (options: MultipleSelectorOption[]) => void;
  /** Maximum number of selected options */
  maxSelected?: number;
  /** Callback when max selection is reached */
  onMaxSelected?: (maxLimit: number) => void;
  /** Hide placeholder when options are selected */
  hidePlaceholderWhenSelected?: boolean;
  /** Disable the selector */
  disabled?: boolean;
  /** Group options by this key */
  groupBy?: string;
  /** Additional className for container */
  className?: string;
  /** Additional className for badges */
  badgeClassName?: string;
  /** Select first item by default (cmdk behavior) */
  selectFirstItem?: boolean;
  /** Allow creating new options */
  creatable?: boolean;
  /** Props for Command component */
  commandProps?: React.ComponentPropsWithoutRef<typeof Command>;
  /** Props for input element */
  inputProps?: Omit<
    React.ComponentPropsWithoutRef<typeof CommandPrimitive.Input>,
    "value" | "placeholder" | "disabled"
  >;
  /** Hide clear all button */
  hideClearAllButton?: boolean;
}

export interface MultipleSelectorRef {
  selectedValue: MultipleSelectorOption[];
  input: HTMLInputElement;
  focus: () => void;
  reset: () => void;
}

/**
 * Debounced value hook.
 *
 * @deprecated Re-export of the canonical {@link useDebouncedValue} from
 * `@nebutra/ui/hooks` (backed by `usehooks-ts`). Kept for backwards-compat of
 * the `@nebutra/ui/primitives` barrel; import `useDebouncedValue` directly.
 */
export function useDebounce<T>(value: T, delay?: number): T {
  return useDebouncedValue(value, delay ?? 500);
}

function transToGroupOption(options: MultipleSelectorOption[], groupBy?: string): GroupOption {
  if (options.length === 0) return {};
  if (!groupBy) return { "": options };

  const groupOption: GroupOption = {};
  options.forEach((option) => {
    const key = (option[groupBy] as string) || "";
    if (!groupOption[key]) groupOption[key] = [];
    groupOption[key].push(option);
  });
  return groupOption;
}

function removePickedOption(
  groupOption: GroupOption,
  picked: MultipleSelectorOption[],
): GroupOption {
  const cloneOption = JSON.parse(JSON.stringify(groupOption)) as GroupOption;
  for (const [key, value] of Object.entries(cloneOption)) {
    cloneOption[key] = value.filter((val) => !picked.find((p) => p.value === val.value));
  }
  return cloneOption;
}

function isOptionsExist(groupOption: GroupOption, targetOption: MultipleSelectorOption[]): boolean {
  for (const [, value] of Object.entries(groupOption)) {
    if (value.some((option) => targetOption.find((p) => p.value === option.value))) {
      return true;
    }
  }
  return false;
}

/**
 * Custom CommandEmpty that renders correctly with cmdk
 */
const CommandEmpty = ({
  className,
  ref: forwardedRef,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Empty> & {
  ref?: Ref<HTMLDivElement> | undefined;
}) => {
  const render = useCommandState((state) => state.filtered.count === 0);
  if (!render) return null;

  return (
    <div
      ref={forwardedRef}
      className={cn("px-2 py-4 text-center text-sm", className)}
      cmdk-empty=""
      role="presentation"
      {...props}
    />
  );
};
CommandEmpty.displayName = "CommandEmpty";

/**
 * MultipleSelector - A multi-select component with search and create functionality
 *
 * @description
 * Feature-rich multi-select with support for async search, grouping,
 * creatable options, and keyboard navigation.
 *
 * @example Basic usage
 * ```tsx
 * <MultipleSelector
 *   defaultOptions={[
 *     { value: "react", label: "React" },
 *     { value: "vue", label: "Vue" },
 *   ]}
 *   placeholder="Select frameworks..."
 *   onChange={(options) => console.log(options)}
 * />
 * ```
 *
 * @example With async search
 * ```tsx
 * <MultipleSelector
 *   onSearch={async (query) => {
 *     const results = await fetchOptions(query);
 *     return results;
 *   }}
 *   placeholder="Search..."
 *   loadingIndicator={<Spinner />}
 * />
 * ```
 *
 * @example Creatable
 * ```tsx
 * <MultipleSelector
 *   creatable
 *   defaultOptions={options}
 *   placeholder="Select or create..."
 * />
 * ```
 *
 * @example With max selection
 * ```tsx
 * <MultipleSelector
 *   maxSelected={3}
 *   onMaxSelected={(max) => toast(`Max ${max} items`)}
 *   defaultOptions={options}
 * />
 * ```
 */
const MultipleSelector = ({
  ref,
  value,
  onChange,
  placeholder,
  defaultOptions: arrayDefaultOptions = [],
  options: arrayOptions,
  delay,
  onSearch,
  onSearchSync,
  loadingIndicator,
  emptyIndicator,
  maxSelected = Number.MAX_SAFE_INTEGER,
  onMaxSelected,
  hidePlaceholderWhenSelected,
  disabled,
  groupBy,
  className,
  badgeClassName,
  selectFirstItem = true,
  creatable = false,
  triggerSearchOnFocus = false,
  commandProps,
  inputProps,
  hideClearAllButton = false,
}: MultipleSelectorProps & { ref?: React.Ref<MultipleSelectorRef> | undefined }) => {
  const inputRef = React.useRef<HTMLInputElement>(null);
  const [open, setOpen] = React.useState(false);
  const [onScrollbar, setOnScrollbar] = React.useState(false);
  const [isLoading, setIsLoading] = React.useState(false);
  const dropdownRef = React.useRef<HTMLDivElement>(null);

  const [selected, setSelected] = React.useState<MultipleSelectorOption[]>(value || []);
  const [options, setOptions] = React.useState<GroupOption>(
    transToGroupOption(arrayDefaultOptions, groupBy),
  );
  const [inputValue, setInputValue] = React.useState("");
  const debouncedSearchTerm = useDebouncedValue(inputValue, delay || 500);

  React.useImperativeHandle(
    ref,
    () => ({
      selectedValue: [...selected],
      input: inputRef.current as HTMLInputElement,
      focus: () => inputRef?.current?.focus(),
      reset: () => setSelected([]),
    }),
    [selected],
  );

  const handleClickOutside = React.useCallback((event: MouseEvent | TouchEvent) => {
    if (
      dropdownRef.current &&
      !dropdownRef.current.contains(event.target as Node) &&
      inputRef.current &&
      !inputRef.current.contains(event.target as Node)
    ) {
      setOpen(false);
      inputRef.current.blur();
    }
  }, []);

  const handleUnselect = React.useCallback(
    (option: MultipleSelectorOption) => {
      const newOptions = selected.filter((s) => s.value !== option.value);
      setSelected(newOptions);
      onChange?.(newOptions);
    },
    [onChange, selected],
  );

  const handleKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLDivElement>) => {
      const input = inputRef.current;
      if (input) {
        if (e.key === "Delete" || e.key === "Backspace") {
          if (input.value === "" && selected.length > 0) {
            const lastSelectOption = selected[selected.length - 1];
            if (lastSelectOption && !lastSelectOption.fixed) {
              handleUnselect(lastSelectOption);
            }
          }
        }
        if (e.key === "Escape") {
          input.blur();
        }
      }
    },
    [handleUnselect, selected],
  );

  useEffect(() => {
    if (open) {
      document.addEventListener("mousedown", handleClickOutside);
      document.addEventListener("touchend", handleClickOutside);
    } else {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("touchend", handleClickOutside);
    }
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("touchend", handleClickOutside);
    };
  }, [open, handleClickOutside]);

  useEffect(() => {
    if (value) setSelected(value);
  }, [value]);

  useEffect(() => {
    if (!arrayOptions || onSearch) return;
    const newOption = transToGroupOption(arrayOptions, groupBy);
    if (JSON.stringify(newOption) !== JSON.stringify(options)) {
      setOptions(newOption);
    }
  }, [arrayOptions, groupBy, onSearch, options]);

  useEffect(() => {
    const doSearchSync = () => {
      const res = onSearchSync?.(debouncedSearchTerm);
      setOptions(transToGroupOption(res || [], groupBy));
    };

    const exec = async () => {
      if (!onSearchSync || !open) return;
      if (triggerSearchOnFocus) doSearchSync();
      if (debouncedSearchTerm) doSearchSync();
    };

    void exec();
  }, [debouncedSearchTerm, groupBy, open, triggerSearchOnFocus, onSearchSync]);

  useEffect(() => {
    const doSearch = async () => {
      setIsLoading(true);
      const res = await onSearch?.(debouncedSearchTerm);
      setOptions(transToGroupOption(res || [], groupBy));
      setIsLoading(false);
    };

    const exec = async () => {
      if (!onSearch || !open) return;
      if (triggerSearchOnFocus) await doSearch();
      if (debouncedSearchTerm) await doSearch();
    };

    void exec();
  }, [debouncedSearchTerm, groupBy, open, triggerSearchOnFocus, onSearch]);

  const CreatableItem = () => {
    if (!creatable) return undefined;
    if (
      isOptionsExist(options, [{ value: inputValue, label: inputValue }]) ||
      selected.find((s) => s.value === inputValue)
    ) {
      return undefined;
    }

    const Item = (
      <CommandItem
        value={inputValue}
        className="cursor-pointer mx-1 mb-1"
        onMouseDown={(e: React.MouseEvent) => {
          e.preventDefault();
          e.stopPropagation();
        }}
        onSelect={(value: string) => {
          if (selected.length >= maxSelected) {
            onMaxSelected?.(selected.length);
            return;
          }
          setInputValue("");
          const newOptions = [...selected, { value, label: value }];
          setSelected(newOptions);
          onChange?.(newOptions);
        }}
      >
        {`Create "${inputValue}"`}
      </CommandItem>
    );

    if (!onSearch && inputValue.length > 0) return Item;
    if (onSearch && debouncedSearchTerm.length > 0 && !isLoading) return Item;
    return undefined;
  };

  const EmptyItem = React.useCallback(() => {
    if (!emptyIndicator) return undefined;

    if (onSearch && !creatable && Object.keys(options).length === 0) {
      return (
        <CommandItem value="-" disabled>
          {emptyIndicator}
        </CommandItem>
      );
    }

    return <CommandEmpty>{emptyIndicator}</CommandEmpty>;
  }, [creatable, emptyIndicator, onSearch, options]);

  const selectables = React.useMemo<GroupOption>(
    () => removePickedOption(options, selected),
    [options, selected],
  );

  const commandFilter = React.useCallback<() => MultipleSelectorCommandFilter | undefined>(() => {
    if (commandProps?.filter) return commandProps.filter;

    if (creatable) {
      return (value: string, search: string) => {
        return value.toLowerCase().includes(search.toLowerCase()) ? 1 : -1;
      };
    }
    return undefined;
  }, [creatable, commandProps?.filter]);
  const resolvedCommandFilter = commandFilter();
  const commandFilterProps =
    resolvedCommandFilter === undefined ? {} : { filter: resolvedCommandFilter };

  return (
    <Command
      ref={dropdownRef}
      {...commandProps}
      onKeyDown={(e: React.KeyboardEvent<HTMLDivElement>) => {
        handleKeyDown(e);
        commandProps?.onKeyDown?.(e);
      }}
      className={cn("h-auto overflow-visible bg-transparent", commandProps?.className)}
      shouldFilter={
        commandProps?.shouldFilter !== undefined ? commandProps.shouldFilter : !onSearch
      }
      {...commandFilterProps}
    >
      <div
        className={cn(
          "relative min-h-[38px] rounded-[var(--radius-lg)] border border-input text-sm transition-shadow has-[:focus-visible]:border-ring has-[:focus-visible]:outline-none has-[:focus-visible]:ring-[3px] has-[:focus-visible]:ring-ring/20 has-[:disabled]:cursor-not-allowed has-[:disabled]:opacity-50",
          {
            "p-1": selected.length !== 0,
            "cursor-text": !disabled && selected.length !== 0,
          },
          !hideClearAllButton && "pe-9",
          className,
        )}
        onPointerDown={(event) => {
          if (disabled) return;
          if (event.target instanceof HTMLButtonElement) return;
          inputRef?.current?.focus();
        }}
      >
        <div className="flex flex-wrap gap-1">
          {selected.map((option) => (
            <div
              key={option.value}
              className={cn(
                "animate-fadeIn relative inline-flex h-7 cursor-default items-center rounded-[var(--radius-md)] border border-solid bg-background pe-7 pl-2 ps-2 text-xs font-medium text-secondary-foreground transition-[background-color,border-color,box-shadow,color,opacity,transform] hover:bg-background disabled:cursor-not-allowed disabled:opacity-50 data-[fixed]:pe-2",
                badgeClassName,
              )}
              data-fixed={option.fixed}
              data-disabled={disabled || undefined}
            >
              {option.label}
              {!option.fixed && (
                <button
                  type="button"
                  className="absolute -inset-y-px -end-px flex size-7 items-center justify-center rounded-e-lg border border-transparent p-0 text-muted-foreground/80 outline-0 transition-colors hover:text-foreground focus-visible:outline focus-visible:outline-2 focus-visible:outline-ring/70"
                  onKeyDown={(e) => {
                    if (e.key === "Enter") handleUnselect(option);
                  }}
                  onMouseDown={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                  }}
                  onClick={() => handleUnselect(option)}
                  aria-label="Remove"
                >
                  <XIcon size={14} strokeWidth={2} aria-hidden="true" />
                </button>
              )}
            </div>
          ))}
          <CommandPrimitive.Input
            {...inputProps}
            ref={inputRef}
            value={inputValue}
            disabled={disabled}
            onValueChange={(value: string) => {
              setInputValue(value);
              inputProps?.onValueChange?.(value);
            }}
            onBlur={(event: React.FocusEvent<HTMLInputElement>) => {
              if (!onScrollbar) setOpen(false);
              inputProps?.onBlur?.(event);
            }}
            onFocus={(event: React.FocusEvent<HTMLInputElement>) => {
              setOpen(true);
              if (triggerSearchOnFocus) onSearch?.(debouncedSearchTerm);
              inputProps?.onFocus?.(event);
            }}
            placeholder={hidePlaceholderWhenSelected && selected.length !== 0 ? "" : placeholder}
            className={cn(
              "flex-1 bg-transparent outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed",
              {
                "w-full": hidePlaceholderWhenSelected,
                "px-3 py-2": selected.length === 0,
                "ml-1": selected.length !== 0,
              },
              inputProps?.className,
            )}
          />
          <button
            type="button"
            onClick={() => {
              setSelected(selected.filter((s) => s.fixed));
              onChange?.(selected.filter((s) => s.fixed));
            }}
            className={cn(
              "absolute end-0 top-0 flex size-9 items-center justify-center rounded-[var(--radius-lg)] border border-transparent text-muted-foreground/80 transition-colors hover:text-foreground focus-visible:outline focus-visible:outline-2 focus-visible:outline-ring/70",
              (hideClearAllButton ||
                disabled ||
                selected.length < 1 ||
                selected.filter((s) => s.fixed).length === selected.length) &&
                "hidden",
            )}
            aria-label="Clear all"
          >
            <XIcon size={16} strokeWidth={2} aria-hidden="true" />
          </button>
        </div>
      </div>
      <div className="relative">
        <div
          className={cn(
            "absolute top-2 z-10 w-full overflow-hidden rounded-[var(--radius-lg)] border border-input",
            "data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95",
            !open && "hidden",
          )}
          data-state={open ? "open" : "closed"}
        >
          {open && (
            <CommandList
              className="bg-popover text-popover-foreground shadow-lg shadow-black/5 outline-none"
              onMouseLeave={() => setOnScrollbar(false)}
              onMouseEnter={() => setOnScrollbar(true)}
              onMouseUp={() => inputRef?.current?.focus()}
            >
              {isLoading ? (
                loadingIndicator
              ) : (
                <>
                  {EmptyItem()}
                  {CreatableItem()}
                  {!selectFirstItem && <CommandItem value="-" className="hidden" />}
                  {Object.entries(selectables).map(([key, dropdowns]) => (
                    <CommandGroup key={key} heading={key} className="h-full overflow-auto">
                      {dropdowns.map((option) => (
                        <CommandItem
                          key={option.value}
                          value={option.value}
                          {...(option.disable ? { disabled: option.disable } : {})}
                          onMouseDown={(e: React.MouseEvent) => {
                            e.preventDefault();
                            e.stopPropagation();
                          }}
                          onSelect={() => {
                            if (selected.length >= maxSelected) {
                              onMaxSelected?.(selected.length);
                              return;
                            }
                            setInputValue("");
                            const newOptions = [...selected, option];
                            setSelected(newOptions);
                            onChange?.(newOptions);
                          }}
                          className={cn(
                            "cursor-pointer",
                            option.disable && "cursor-not-allowed opacity-50",
                          )}
                        >
                          {option.label}
                        </CommandItem>
                      ))}
                    </CommandGroup>
                  ))}
                </>
              )}
            </CommandList>
          )}
        </div>
      </div>
    </Command>
  );
};

MultipleSelector.displayName = "MultipleSelector";

export { MultipleSelector };
